// Provenancecheck verifies the generated provenance records in the nvidia
// module. Run it after regenerating:
//
//	make -C nvidia provenance-check
//
// It checks four properties. The first three keep a record portable, so that
// a clone reproduces the same bytes on a different host:
//
//  1. no host paths, such as /Users or /Volumes
//  2. no build sandbox paths, such as go-build or /var/folders
//  3. cwd recorded as "."
//
// The fourth keeps a record useful. Ten packages are generated by gen-nvidia
// and share one generator field; only argv separates them, as -api cudnn
// against -api cupti -clang=false. If argv redaction ever collapses two of
// them, provenance stops saying which recipe produced which package, and
// nothing else records it. That failure is silent, so it is checked here
// rather than left to a reader.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type record struct {
	Generator string   `json:"generator"`
	Cwd       string   `json:"cwd"`
	Argv      []string `json:"argv"`
}

var hostPrefixes = []string{"/Users/", "/Volumes/", "/home/"}

var sandboxMarkers = []string{"go-build", "/var/folders/"}

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "provenancecheck:", err)
		os.Exit(1)
	}
}

func run() error {
	files, err := filepath.Glob("*/*provenance.json")
	if err != nil {
		return err
	}
	if len(files) == 0 {
		return fmt.Errorf("no provenance records found; run from the nvidia module root")
	}
	sort.Strings(files)

	var problems []string
	argvByGenerator := make(map[string]map[string]string)
	for _, file := range files {
		data, err := os.ReadFile(file)
		if err != nil {
			return err
		}
		var rec record
		if err := json.Unmarshal(data, &rec); err != nil {
			return fmt.Errorf("%s: %v", file, err)
		}
		blob := string(data)
		for _, prefix := range hostPrefixes {
			if strings.Contains(blob, prefix) {
				problems = append(problems, fmt.Sprintf("%s: host path %s", file, prefix))
			}
		}
		for _, marker := range sandboxMarkers {
			if strings.Contains(blob, marker) {
				problems = append(problems, fmt.Sprintf("%s: build sandbox path %s", file, marker))
			}
		}
		if rec.Cwd != "." {
			problems = append(problems, fmt.Sprintf("%s: cwd is %q, want %q", file, rec.Cwd, "."))
		}
		if rec.Generator == "" {
			problems = append(problems, fmt.Sprintf("%s: no generator recorded", file))
			continue
		}
		if argvByGenerator[rec.Generator] == nil {
			argvByGenerator[rec.Generator] = make(map[string]string)
		}
		argvByGenerator[rec.Generator][file] = strings.Join(rec.Argv, " ")
	}
	problems = append(problems, collisions(argvByGenerator)...)

	for _, p := range problems {
		fmt.Fprintln(os.Stderr, p)
	}
	fmt.Printf("%d records checked, %d problems\n", len(files), len(problems))
	if len(problems) > 0 {
		os.Exit(1)
	}
	return nil
}

// collisions reports generators that produced two packages under one argv.
func collisions(argvByGenerator map[string]map[string]string) []string {
	var out []string
	for generator, byFile := range argvByGenerator {
		sharers := make(map[string][]string)
		for file, argv := range byFile {
			sharers[argv] = append(sharers[argv], file)
		}
		for _, files := range sharers {
			if len(files) < 2 {
				continue
			}
			sort.Strings(files)
			out = append(out, fmt.Sprintf("%s: %d packages share one argv, so provenance cannot say which recipe made which: %s",
				generator, len(files), strings.Join(files, ", ")))
		}
	}
	sort.Strings(out)
	return out
}
